// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract LTVNFT {
    string public name;
    string public symbol;
    uint256 public totalSupply;

    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);

    constructor(string memory _name, string memory _symbol) {
        name = _name;
        symbol = _symbol;
    }

    function balanceOf(address owner) public view returns (uint256) {
        require(owner != address(0), "Invalid address");
        return _balances[owner];
    }

    function ownerOf(uint256 tokenId) public view returns (address) {
        address owner = _owners[tokenId];
        require(owner != address(0), "Token doesn't exist");
        return owner;
    }

    function mint(address to, uint256 tokenId) public {
        require(to != address(0), "Cannot mint to zero address");
        require(_owners[tokenId] == address(0), "Token already exists");

        _owners[tokenId] = to;
        _balances[to] += 1;
        totalSupply += 1;

        emit Transfer(address(0), to, tokenId);
    }

    // --- the missing piece EnglishAuction.start() actually calls ---

    function getApproved(uint256 tokenId) public view returns (address) {
        require(_owners[tokenId] != address(0), "Token doesn't exist");
        return _tokenApprovals[tokenId];
    }

    function approve(address to, uint256 tokenId) public {
        address tokenOwner = ownerOf(tokenId);
        require(msg.sender == tokenOwner, "Not the token owner");
        require(to != tokenOwner, "Cannot approve current owner");

        _tokenApprovals[tokenId] = to;
        emit Approval(tokenOwner, to, tokenId);
    }

    function transferFrom(address from, address to, uint256 tokenId) public {
        address tokenOwner = ownerOf(tokenId);
        require(tokenOwner == from, "From is not the owner");
        require(to != address(0), "Cannot transfer to zero address");
        require(
            msg.sender == tokenOwner || msg.sender == _tokenApprovals[tokenId],
            "Not owner or approved"
        );

        delete _tokenApprovals[tokenId]; // clear the now-stale approval

        _balances[from] -= 1;
        _balances[to] += 1;
        _owners[tokenId] = to;

        emit Transfer(from, to, tokenId);
    }
}
```

**The real deployment sequence in Remix, in order:**

```text
1. Deploy LTVNFT("LTV Auction NFT", "LTVNFT") from the seller's account.
2. Call mint(sellerAddress, 1) from the seller — seller now owns tokenId 1.
3. Deploy EnglishAuction(ltvNftAddress, 1, startingBidInWei) from the seller.
4. Call approve(englishAuctionAddress, 1) on LTVNFT, from the seller.
   <- required BEFORE step 5, or start() will revert
5. Call start() on EnglishAuction, from the seller.
6. Confirm: ownerOf(1) on LTVNFT now returns the EnglishAuction contract's address.
```
